css:
.mhex-sim-container {
    padding: 28px;
    background: #0c1929;
    min-height: 100vh;
    font-family: 'Segoe UI', -apple-system, 'Helvetica Neue', Arial, sans-serif;
    color: #c8d6e5;
}
.mhex-sim-header {
    background: linear-gradient(135deg, #0f2744 0%, #1a3a5c 60%, #1e4d6e 100%);
    border-radius: 12px;
    padding: 36px 32px 28px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(212,175,55,0.2);
}
.mhex-sim-header::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #d4af37, #f0c75e, #d4af37);
}
.mhex-sim-header-flag {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}
.mhex-sim-flag-icon {
    font-size: 1.6rem;
}
.mhex-sim-header-tag {
    background: rgba(212,175,55,0.15);
    color: #f0c75e;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 4px;
    border: 1px solid rgba(212,175,55,0.3);
}
.mhex-sim-container h1 {
    color: #ffffff;
    font-size: 1.65rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.mhex-sim-subtitle {
    color: #8eafc8;
    font-size: 0.92rem;
    margin: 0;
    font-weight: 400;
}
.mhex-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #6b8299;
    margin-bottom: 20px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.mhex-sim-period-counter span {
    margin: 0 3px;
}
.mhex-sim-period-counter span:nth-child(2),
.mhex-sim-period-counter span:nth-child(4) {
    color: #f0c75e;
    font-weight: 700;
    font-size: 1.05rem;
}
.mhex-sim-briefing {
    background: linear-gradient(135deg, rgba(212,175,55,0.06) 0%, rgba(30,77,110,0.15) 100%);
    border: 1px solid rgba(212,175,55,0.18);
    border-left: 4px solid #d4af37;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 24px;
    line-height: 1.6;
}
.mhex-sim-briefing-badge {
    font-size: 0.7rem;
    font-weight: 700;
    color: #f0c75e;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
}
.mhex-sim-briefing p {
    margin: 0;
    color: #a8c0d6;
    font-size: 0.9rem;
}
.mhex-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.mhex-sim-kpi-card {
    background: #111f33;
    border: 1px solid #1c3450;
    border-radius: 10px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, border-color 0.2s ease;
}
.mhex-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: #2a4a6b;
}
.mhex-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
}
.mhex-kpi-cash::before { background: #d4af37; }
.mhex-kpi-revenue::before { background: #3498db; }
.mhex-kpi-margin-a::before { background: #27ae60; }
.mhex-kpi-margin-b::before { background: #8e44ad; }
.mhex-kpi-profit::before { background: #2ecc71; }
.mhex-kpi-tariff::before { background: #e74c3c; }
.mhex-sim-kpi-icon {
    font-size: 1.2rem;
    margin-bottom: 6px;
}
.mhex-sim-kpi-label {
    color: #5a7a99;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 6px;
    font-weight: 600;
}
.mhex-sim-kpi-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #e8f0f8;
}
.mhex-kpi-cash .mhex-sim-kpi-value { color: #f0c75e; }
.mhex-kpi-revenue .mhex-sim-kpi-value { color: #5dade2; }
.mhex-kpi-margin-a .mhex-sim-kpi-value { color: #2ecc71; }
.mhex-kpi-margin-b .mhex-sim-kpi-value { color: #a569bd; }
.mhex-kpi-profit .mhex-sim-kpi-value { color: #2ecc71; }
.mhex-kpi-tariff .mhex-sim-kpi-value { font-size: 1.1rem; }
.mhex-sim-controls {
    background: #111f33;
    border: 1px solid #1c3450;
    border-radius: 10px;
    padding: 28px;
    margin-bottom: 28px;
}
.mhex-sim-controls h3 {
    color: #e8f0f8;
    font-size: 1.05rem;
    font-weight: 600;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1c3450;
}
.mhex-sim-control-group {
    margin-bottom: 16px;
}
.mhex-sim-control-group label {
    display: block;
    color: #8eafc8;
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
}
.mhex-sim-control-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.mhex-sim-container select,
.mhex-sim-container input[type="number"] {
    width: 100%;
    background: #0c1929;
    border: 1px solid #2a4a6b;
    color: #e8f0f8;
    border-radius: 6px;
    padding: 10px 14px;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.mhex-sim-container select:focus,
.mhex-sim-container input[type="number"]:focus {
    outline: none;
    border-color: #d4af37;
    box-shadow: 0 0 0 3px rgba(212,175,55,0.15);
}
.mhex-sim-container select option {
    background: #0c1929;
    color: #e8f0f8;
}
.mhex-sim-btn-row {
    display: flex;
    gap: 12px;
    margin-top: 20px;
    align-items: center;
}
.mhex-sim-submit-btn {
    background: linear-gradient(135deg, #d4af37, #c49b2a);
    border: none;
    color: #0c1929;
    font-weight: 700;
    font-size: 0.95rem;
    padding: 12px 32px;
    border-radius: 6px;
    letter-spacing: 0.03em;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.mhex-sim-submit-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(212,175,55,0.3);
    background: linear-gradient(135deg, #e0be4a, #d4af37);
    color: #0c1929;
}
.mhex-sim-undo-btn {
    color: #6b8299;
    border-color: #2a4a6b;
    font-size: 0.8rem;
}
.mhex-sim-undo-btn:hover {
    color: #a8c0d6;
    border-color: #3a5a7b;
    background: rgba(42,74,107,0.2);
}
.mhex-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 28px;
}
.mhex-sim-chart-wrap {
    background: #111f33;
    border: 1px solid #1c3450;
    border-radius: 10px;
    padding: 20px;
    height: 280px;
}
.mhex-sim-history {
    background: #111f33;
    border: 1px solid #1c3450;
    border-radius: 10px;
    padding: 20px;
    overflow-x: auto;
}
.mhex-sim-container .table {
    color: #c8d6e5;
    margin: 0;
}
.mhex-sim-container .table thead th {
    background: #0c1929;
    color: #8eafc8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-color: #1c3450;
    padding: 10px 12px;
    font-weight: 700;
}
.mhex-sim-container .table tbody td {
    border-color: #1c3450;
    padding: 8px 12px;
    font-size: 0.85rem;
    vertical-align: middle;
}
.mhex-sim-container .table tbody tr:hover {
    background: rgba(212,175,55,0.04);
}
.mhex-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(17,31,51,0.5);
}
@media (max-width: 768px) {
    .mhex-sim-container { padding: 16px; }
    .mhex-sim-kpi-grid { grid-template-columns: 1fr 1fr; }
    .mhex-sim-control-row { grid-template-columns: 1fr; }
    .mhex-sim-charts { grid-template-columns: 1fr; }
    .mhex-sim-chart-wrap { height: 220px; }
    .mhex-sim-header { padding: 24px 20px 20px; }
    .mhex-sim-container h1 { font-size: 1.3rem; }
    .mhex-sim-btn-row { flex-direction: column; }
}

