                    tag_es: 'RONDA 4 — ESTRATEGIA DE LARGO PLAZO',
                    desc_en: 'The market has stabilized. Guatemalan competitors have captured share with CAFTA-compliant supply chains. You must decide the <strong>future of each product line</strong>:<br><br>Line A (basic polyester) faces permanent margin compression. Line B (technical nylon) has higher margins but also faces pressure. Consider: maintain, reduce, or discontinue each line. Present your 18-month plan — the board expects a path to $2M+ annual gross profit.',
                    desc_es: 'El mercado se ha estabilizado. Competidores guatemaltecos han capturado participación con cadenas CAFTA-DR. Debe decidir el <strong>futuro de cada línea de producto</strong>:<br><br>Línea A (poliéster básico) enfrenta compresión permanente de margen. Línea B (nylon técnico) tiene mayores márgenes pero también enfrenta presión. Considere: mantener, reducir o descontinuar cada línea. Presente su plan de 18 meses — la junta espera un camino hacia $2M+ de ganancia bruta anual.',
                    tariffActive: true,
                    demandMultiplier: 0.68,
                    clientPressure: 0.32
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2000000,
                    totalRevenue: 0,
                    totalProfit: 0,
                    currentSupplier: 'china',
                    lineACost: 1.80,
                    lineBCost: 3.45,
                    profitHistory: [],
                    revenueHistory: [],
                    marginAHistory: [],
                    marginBHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    supplier: 'china',
                    lineAPrice: 2.40,
                    lineBPrice: 4.50,
                    lineAVolume: 2800,
                    lineBVolume: 1200
                };
            }
            var self = this;
            var fw = window.mySimulation;
            if (fw && typeof fw.setLang === 'function' && !fw.__mhexLangPatched) {
                fw.__mhexLangPatched = true;
                var origSetLang = fw.setLang.bind(fw);
                fw.setLang = function(lang) { origSetLang(lang); try { self._updateBriefing(fw.state); } catch (e) {} };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var supplierEl = document.getElementById('supplierSelect');
            if (supplierEl) decisions.supplier = supplierEl.value;

            var lineAPriceEl = document.getElementById('lineAPriceInput');
            if (lineAPriceEl) decisions.lineAPrice = parseFloat(lineAPriceEl.value);

            var lineBPriceEl = document.getElementById('lineBPriceInput');
            if (lineBPriceEl) decisions.lineBPrice = parseFloat(lineBPriceEl.value);

            var lineAVolEl = document.getElementById('lineAVolumeInput');
            if (lineAVolEl) decisions.lineAVolume = parseInt(lineAVolEl.value);

            var lineBVolEl = document.getElementById('lineBVolumeInput');
            if (lineBVolEl) decisions.lineBVolume = parseInt(lineBVolEl.value);

            if (!decisions.lineAPrice || decisions.lineAPrice < 1.80 || decisions.lineAPrice > 3.50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_a_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.lineBPrice || decisions.lineBPrice < 3.00 || decisions.lineBPrice > 6.00) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_b_warning'), 'warning'
                );
                return false;
            }
            // a blank volume is NaN and passes both bounds, which would poison cash and profit for the rest of the game
            if (isNaN(decisions.lineAVolume) || decisions.lineAVolume < 0 || decisions.lineAVolume > 3000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('vol_a_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.lineBVolume) || decisions.lineBVolume < 0 || decisions.lineBVolume > 1500) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('vol_b_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var supplierPremiumA = 0;
            var supplierPremiumB = 0;
            if (d.supplier === 'mexico') {
                supplierPremiumA = 0.15;
                supplierPremiumB = 0.20;
            } else if (d.supplier === 'usa') {
                supplierPremiumA = 0.18;
                supplierPremiumB = 0.22;
            }

            var costA = 1.80 + supplierPremiumA;
            var costB = 3.45 + supplierPremiumB;

            var tariffApplies = round.tariffActive && d.supplier === 'china';
            var effectivePriceA = tariffApplies ? d.lineAPrice * 1.25 : d.lineAPrice;
            var effectivePriceB = tariffApplies ? d.lineBPrice * 1.25 : d.lineBPrice;

            var refPriceA = 2.15;
            var refPriceB = 4.25;

            var demandRatioA = Math.min(1.15, Math.max(0.15, Math.pow(refPriceA / Math.max(effectivePriceA, 0.50), 1.4)));
            var demandRatioB = Math.min(1.15, Math.max(0.20, Math.pow(refPriceB / Math.max(effectivePriceB, 1.00), 1.1)));

            demandRatioA *= round.demandMultiplier;
            demandRatioB *= round.demandMultiplier;

            if (round.clientPressure > 0) {
                if (effectivePriceA > 2.25) {
                    demandRatioA *= (1 - round.clientPressure * 0.8);
                }
                if (effectivePriceB > 4.35) {
                    demandRatioB *= (1 - round.clientPressure * 0.5);
                }
            }

            var targetA = d.lineAVolume * 1000;
            var targetB = d.lineBVolume * 1000;
            var maxDemandA = 2800000 * demandRatioA / 4;
            var maxDemandB = 1200000 * demandRatioB / 4;
            var actualA = Math.round(Math.min(targetA / 4, maxDemandA));
            var actualB = Math.round(Math.min(targetB / 4, maxDemandB));

            var revenueA = actualA * d.lineAPrice;
            var revenueB = actualB * d.lineBPrice;
            var totalRevenue = revenueA + revenueB;

            var totalCostA = actualA * costA;
            var totalCostB = actualB * costB;
            var fixedCosts = 125000;
            var totalCosts = totalCostA + totalCostB + fixedCosts;

            var profitA = revenueA - totalCostA;
            var profitB = revenueB - totalCostB;
            var totalProfit = profitA + profitB - fixedCosts;

            var marginA = revenueA > 0 ? ((d.lineAPrice - costA) / d.lineAPrice * 100) : 0;
            var marginB = revenueB > 0 ? ((d.lineBPrice - costB) / d.lineBPrice * 100) : 0;

            ds.cash += totalProfit;
            ds.totalRevenue += totalRevenue;
            ds.totalProfit += totalProfit;
            ds.currentSupplier = d.supplier;
            ds.lineACost = costA;
            ds.lineBCost = costB;

            ds.profitHistory.push(Math.round(totalProfit));
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.marginAHistory.push(Math.round(marginA * 10) / 10);
            ds.marginBHistory.push(Math.round(marginB * 10) / 10);

            // Platform score: cumulative profit as getPerformanceSummary sums it, mapped through its verdict bands. Needs improvement 0 to 49 from minus 1.7M (worst reachable) to 0.5M, adequate 50 to 69 up to 1M, good 70 to 84 up to 1.5M, excellent 85 to 100 above 1.5M with the latest Line A margin over 15 percent, 100 at 2.6M (best reachable).
            var pfProfit = ds.profitHistory.reduce(function(s, p) { return s + p; }, 0);
            var pfMarginA = ds.marginAHistory[ds.marginAHistory.length - 1];
            var pfScore;
            if (pfProfit > 1500000 && pfMarginA > 15) { pfScore = 85 + 15 * Math.min(1, (pfProfit - 1500000) / 1100000); }
            else if (pfProfit > 1000000) { pfScore = 70 + 14 * Math.min(1, (pfProfit - 1000000) / 500000); }
            else if (pfProfit > 500000) { pfScore = 50 + 19 * (pfProfit - 500000) / 500000; }
            else { pfScore = 49 * Math.max(0, (pfProfit + 1700000) / 2200000); }
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(pfScore))) });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                supplier: d.supplier,
                lineAPrice: d.lineAPrice,
                lineBPrice: d.lineBPrice,
                actualVolumeA: actualA,
                actualVolumeB: actualB,
                revenueA: Math.round(revenueA),
                revenueB: Math.round(revenueB),
                totalRevenue: Math.round(totalRevenue),
                profitA: Math.round(profitA),
                profitB: Math.round(profitB),
                totalProfit: Math.round(totalProfit),
                marginA: Math.round(marginA * 10) / 10,
                marginB: Math.round(marginB * 10) / 10,
                tariffApplied: tariffApplies,
                cash: Math.round(ds.cash)
            };
        }

