        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.totalProfit : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;
            var finalMarginA = history[history.length - 1].results ? history[history.length - 1].results.marginA : 0;
            var finalMarginB = history[history.length - 1].results ? history[history.length - 1].results.marginB : 0;
            var usedCafta = false;
            for (var i = 0; i < history.length; i++) {
                if (history[i].decisions && history[i].decisions.supplier !== 'china') {
                    usedCafta = true;
                    break;
                }
            }

            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var performance = t('perf_needs');
            var insights = [];

            if (totalProfit > 1500000 && finalMarginA > 15) {
                performance = t('perf_excellent');
                insights.push(t('sum_strong'));
            } else if (totalProfit > 1000000) {
                performance = t('perf_good');
                insights.push(t('sum_solid'));
            } else if (totalProfit > 500000) {
                performance = t('perf_adequate');
                insights.push(t('sum_survived'));
            } else {
                insights.push(t('sum_severe'));
            }

            if (usedCafta) {
                insights.push(t('sum_cafta_yes'));
            } else {
                insights.push(t('sum_cafta_no'));
            }

            if (finalMarginB > 18) {
                insights.push(t('sum_lineb'));
            }

            return {
                totalProfit: totalProfit,
                avgQuarterlyProfit: Math.round(avgProfit),
                finalMarginA: finalMarginA,
                finalMarginB: finalMarginB,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.tariffApplied && results.totalProfit < 100000) {
                return window.mySimulation.t('hint_tariff_pain');
            }
            if (results.marginA < 10 && results.actualVolumeA > 0) {
                return window.mySimulation.t('hint_margin_a_low');
            }
            if (results.totalProfit < 0) {
