        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                var fw = window.mySimulation;
                if (fw && fw.lang) { lang = (String(fw.lang).substring(0, 2) === 'es') ? 'es' : 'en'; }
                else if (document.documentElement.lang) { lang = document.documentElement.lang.substring(0, 2); }
            } catch(e) {}

            var tagEl = document.getElementById('briefingRoundTag');
            if (tagEl) tagEl.innerHTML = lang === 'es' ? round.tag_es : round.tag_en;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = lang === 'es' ? round.desc_es : round.desc_en;
        }
